                    let fs_11 = if s > at { match gap_last_t90 { None => xl_11 || fill_11, Some(q) => q == at && xl_11 } } else { fill_11 };
                    let xs_11 = s == at && xl_11;
                    // `fill(as_run & dot, ~as_run)`: at the byte before the token.
